	SUBQ  $0x00000004, DI
	LEAQ  (DX)(DI*4), CX
	MOVQ  BX, DX
	MOVQ  SI, BX
	XORPS X1, X1

tailtaps:
	MOVSS  (DX), X2
	SHUFPS $0x00, X2, X2
	MOVSS  4(DX), X3
	SHUFPS $0x00, X3, X3
	XORPS  X0, X3
	MOVUPS (CX), X4
	MOVAPS X4, X5
	SHUFPS $0xb1, X5, X5
	MULPS  X2, X4
	MULPS  X3, X5
	ADDPS  X5, X4
	ADDPS  X4, X1
	ADDQ   $0x00000008, DX
	SUBQ   $0x00000008, CX
	DECQ   BX
	JNZ    tailtaps
	MOVUPS X1, (AX)(DI*4)
	JMP    done

	// Fewer floats than one vector: one output at a time
scalar:
	MOVUPS evenSignF32<>+0(SB), X0

scalarloop:
	CMPQ  DI, CX
	JGE   scalardone
	LEAQ  (DX)(DI*4), R8
	MOVQ  BX, R9
	MOVQ  SI, R10
	XORPS X1, X1

scalartaps:
	MOVSD  (R8), X2
	MOVAPS X2, X3
	SHUFPS $0xb1, X3, X3
	MOVSS  (R9), X4
	SHUFPS $0x00, X4, X4
	MOVSS  4(R9), X5
	SHUFPS $0x00, X5, X5
	XORPS  X0, X5
	MULPS  X4, X2
	MULPS  X5, X3
	ADDPS  X3, X2
	ADDPS  X2, X1
	ADDQ   $0x00000008, R9
	SUBQ   $0x00000008, R8
	DECQ   R10
	JNZ    scalartaps
	MOVSD  X1, (AX)(DI*4)
	ADDQ   $0x00000002, DI
	JMP    scalarloop

scalardone:
	RET

done:
	RET

// func dotF32AVX(x []float32, c []float32) float32
// Requires: AVX, SSE
TEXT ·dotF32AVX(SB), NOSPLIT, $0-52
	MOVQ   x_base+0(FP), AX
	MOVQ   c_base+24(FP), CX
	MOVQ   c_len+32(FP), DX
	VXORPS Y0, Y0, Y0
	XORQ   BX, BX
	MOVQ   DX, SI
	ANDQ   $-8, SI

block:
	CMPQ    BX, SI
	JGE     reduce
	VMOVUPS (CX)(BX*4), Y1
	VMULPS  (AX)(BX*4), Y1, Y1
	VADDPS  Y1, Y0, Y0
	ADDQ    $0x00000008, BX
	JMP     block

reduce:
	VEXTRACTF128 $0x01, Y0, X1
	VADDPS       X1, X0, X0
	VZEROUPPER
	MOVHLPS      X0, X2
	ADDPS        X2, X0
	MOVAPS       X0, X1
	SHUFPS       $0x55, X1, X1
	ADDSS        X1, X0

tail:
	CMPQ  BX, DX
	JGE   done
	MOVSS (AX)(BX*4), X1
	MULSS (CX)(BX*4), X1
	ADDSS X1, X0
	INCQ  BX
	JMP   tail

done:
	MOVSS X0, ret+48(FP)
	RET

// func dotF32SSE2(x []float32, c []float32) float32
// Requires: SSE
TEXT ·dotF32SSE2(SB), NOSPLIT, $0-52
	MOVQ  x_base+0(FP), AX
	MOVQ  c_base+24(FP), CX
	MOVQ  c_len+32(FP), DX
	XORPS X0, X0
	XORPS X1, X1
	XORQ  BX, BX
	MOVQ  DX, SI
	ANDQ  $-8, SI

block:
	CMPQ   BX, SI
	JGE    reduce
	MOVUPS (CX)(BX*4), X2
	MOVUPS (AX)(BX*4), X3
	MULPS  X2, X3
	ADDPS  X3, X0
	MOVUPS 16(CX)(BX*4), X2
	MOVUPS 16(AX)(BX*4), X3
	MULPS  X2, X3
	ADDPS  X3, X1
	ADDQ   $0x00000008, BX
	JMP    block

reduce:
	ADDPS   X1, X0
	MOVHLPS X0, X4
	ADDPS   X4, X0
	MOVAPS  X0, X1
	SHUFPS  $0x55, X1, X1
	ADDSS   X1, X0

tail:
	CMPQ  BX, DX
	JGE   done
	MOVSS (AX)(BX*4), X1
	MULSS (CX)(BX*4), X1
	ADDSS X1, X0
	INCQ  BX
	JMP   tail

done:
	MOVSS X0, ret+48(FP)
	RET

// func cdotRealAVX(x []complex64, c []float32) complex64
// Requires: AVX, SSE, SSE2
TEXT ·cdotRealAVX(SB), NOSPLIT, $0-56
	MOVQ   x_base+0(FP), AX
	MOVQ   c_base+24(FP), CX
	MOVQ   c_len+32(FP), DX
	VXORPS Y0, Y0, Y0
	VXORPS Y1, Y1, Y1
	XORQ   BX, BX
	MOVQ   DX, SI
	ANDQ   $-8, SI

block:
	CMPQ       BX, SI
	JGE        reduce
	VMOVUPS    (CX)(BX*4), Y2
	VUNPCKLPS  Y2, Y2, Y3
	VUNPCKHPS  Y2, Y2, Y2
	VPERM2F128 $0x20, Y2, Y3, Y5
	VPERM2F128 $0x31, Y2, Y3, Y2
	VMULPS     (AX)(BX*8), Y5, Y3
	VADDPS     Y3, Y0, Y0
	VMULPS     32(AX)(BX*8), Y2, Y2
	VADDPS     Y2, Y1, Y1
	ADDQ       $0x00000008, BX
	JMP        block

reduce:
	VADDPS       Y1, Y0, Y0
	VEXTRACTF128 $0x01, Y0, X1
	VADDPS       X1, X0, X0
	VZEROUPPER
	MOVHLPS      X0, X4
	ADDPS        X4, X0

	// The real part is in lane 0 and the imaginary part in lane 1
tail:
	CMPQ     BX, DX
	JGE      done
	MOVSD    (AX)(BX*8), X1
	MOVSS    (CX)(BX*4), X2
	UNPCKLPS X2, X2
	MULPS    X2, X1
	ADDPS    X1, X0
	INCQ     BX
	JMP      tail

done:
	MOVSS  X0, ret_real+48(FP)
	MOVAPS X0, X0
	SHUFPS $0x55, X0, X0
	MOVSS  X0, ret_imag+52(FP)
	RET

// func cdotRealSSE2(x []complex64, c []float32) complex64
// Requires: SSE, SSE2
TEXT ·cdotRealSSE2(SB), NOSPLIT, $0-56
	MOVQ  x_base+0(FP), AX
	MOVQ  c_base+24(FP), CX
	MOVQ  c_len+32(FP), DX
	XORPS X0, X0
	XORPS X1, X1
	XORPS X2, X2
	XORPS X3, X3
	XORQ  BX, BX
	MOVQ  DX, SI
	ANDQ  $-8, SI

block:
	CMPQ     BX, SI
	JGE      reduce
	MOVUPS   (CX)(BX*4), X4
	MOVAPS   X4, X5
	UNPCKLPS X5, X5
	UNPCKHPS X4, X4
	MOVUPS   (AX)(BX*8), X6
	MULPS    X5, X6
	ADDPS    X6, X0
	MOVUPS   16(AX)(BX*8), X5
	MULPS    X4, X5
	ADDPS    X5, X1
	MOVUPS   16(CX)(BX*4), X4
	MOVAPS   X4, X5
	UNPCKLPS X5, X5
	UNPCKHPS X4, X4
	MOVUPS   32(AX)(BX*8), X6
	MULPS    X5, X6
	ADDPS    X6, X2
	MOVUPS   48(AX)(BX*8), X5
	MULPS    X4, X5
	ADDPS    X5, X3
	ADDQ     $0x00000008, BX
	JMP      block

reduce:
	ADDPS   X2, X0
	ADDPS   X3, X1
	ADDPS   X1, X0
	MOVHLPS X0, X7
	ADDPS   X7, X0

	// The real part is in lane 0 and the imaginary part in lane 1
tail:
	CMPQ     BX, DX
	JGE      done
	MOVSD    (AX)(BX*8), X1
	MOVSS    (CX)(BX*4), X2
	UNPCKLPS X2, X2
	MULPS    X2, X1
	ADDPS    X1, X0
	INCQ     BX
